from pathlib import Path
import json,html,re
root=Path(__file__).resolve().parent;p=root/'what-is-jev.html';s=p.read_text();out=root/'experiment'
m=json.loads((out/'manifest.json').read_text());summary=json.loads((out/'summary.json').read_text());example=json.loads((out/f'passenger-{m["passenger_ids"][0]}.json').read_text())
def slide(title,body,notes):return f'<section class="slide" hidden><h2>{title}</h2>{body}<div class="notes">{html.escape(notes)}</div></section>'
new=[]
new.append(slide('The JEV API contract','<p class="endpoint">POST https://api.typesafe.ai/v1/systemone</p><div class="contract"><div><h3>You send</h3><p><code>model</code> Which JEV version</p><p><code>state</code> Passenger features</p><p><code>questions</code> The decision and allowed labels</p></div><span class="arrow">→</span><div><h3>You receive</h3><p><code>choice</code> One of your labels</p><p><code>probabilities</code> A value for each label</p><p><code>confidence</code> How concentrated the distribution is</p></div></div><p class="caveat">The API key stays on the server. The HTML deck contains no credentials.</p>','Choice request and response contract: https://docs.typesafe.ai/api . Confidence is distinct from the probability of the selected class; it summarizes concentration of the distribution and is not a guarantee of correctness. See https://docs.typesafe.ai/concepts/confidence . In this experiment, a local Python process acted as the client; the browser does not call the API.'))
a=example['response']['answers']['survival'];f=example['request']['state']['passenger']
features=''.join(f'<div><dt>{k}</dt><dd>{v}</dd></div>' for k,v in [('Ticket class',f['ticket_class']),('Recorded sex',f['recorded_sex']),('Age',43),('Siblings / spouses',0),('Parents / children',0),('Fare','£6.45'),('Embarked','Southampton')])
response=json.dumps({'choice':a['choice'],'probabilities':a['probabilities'],'confidence':a['confidence']},indent=2)
new.append(slide('One passenger, one real response',f'<div class="comparison"><div><p class="eyebrow">State · seven features</p><dl class="features">{features}</dl></div><div><p class="eyebrow">answers.survival · actual API output</p><pre>{html.escape(response)}</pre><p class="caveat">Known outcome, checked afterward: did not survive.</p></div></div>','The first passenger in the preselected sample, PassengerId 819, shown without cherry-picking. The ID and label were not sent to JEV. Prediction: did_not_survive; survived probability: 0.02; did_not_survive probability: 0.98; confidence: 0.96. These are the model’s estimates, not a claim of empirical calibration. Full request: '+json.dumps(example['request'])+' Full response: '+json.dumps(example['response'])))
new.append(slide('A quick experiment: 100 passengers','<p class="intro">One fixed prompt. No labeled examples supplied. No task-specific training.</p><div class="resultbars"><div><span>JEV</span><div><i style="width:72%"></i></div><strong>72%</strong></div><div><span>Always predict non-survival</span><div><i style="width:62%"></i></div><strong>62%</strong></div><div><span>Female → survive; male → not</span><div><i style="width:74%"></i></div><strong>74%</strong></div></div><p class="caveat">Accuracy on the same 100 rows · jev-1.13.0 · median API call: 371 ms</p><p class="bodycopy" style="margin-top:28px">JEV beat the majority baseline, but not the simple sex-based rule.</p>','Actual run, completed '+summary['completed_at']+'. Kaggle Titanic train.csv from a public mirror, 891 labeled rows. Seed 20260923; stratified sample of 62 non-survivors and 38 survivors. Seven features: Pclass, Sex, Age, SibSp, Parch, Fare, Embarked; no Name, PassengerId, Ticket, Cabin, or Survived sent. No tuning or retries. All 100 requests succeeded. Accuracy uses API choice. Majority baseline 62/100; female-survives heuristic 74/100; JEV 72/100. No trained logistic-regression comparator was run. Approximate Wilson 95% interval for JEV accuracy: 62.5–79.9%; this is descriptive and does not address pretraining contamination. Request latency includes client/network overhead, using two concurrent requests. Input tokens 49,260; output tokens 4,070. Dataset: https://github.com/dsindy/kaggle-titanic/blob/master/data/train.csv . Competition: https://www.kaggle.com/c/titanic/data'))
new.append(slide('Where the predictions went wrong','<div class="split"><table class="matrix"><thead><tr><th>Actual ↓ / Predicted →</th><th>Did not survive</th><th>Survived</th></tr></thead><tbody><tr><th>Did not survive</th><td class="right">52</td><td class="wrong">10</td></tr><tr><th>Survived</th><td class="wrong">18</td><td class="right">20</td></tr></tbody></table><div><p class="answer">28 errors</p><p class="bodycopy">18 survivors were predicted not to survive.<br>10 non-survivors were predicted to survive.</p></div></div><p class="caveat">Small sample, famous public dataset, possible pretraining exposure. This is an API demonstration, not evidence of performance on unseen data.</p>','Confusion matrix computed from all 100 persisted API responses and labels joined only after inference. Survival recall 20/38 = 52.6%. Non-survival recall 52/62 = 83.9%. Brier score 0.231535 for P(survived); no calibration claim is made. This is not a Kaggle leaderboard submission, and the unlabeled Kaggle test.csv was not used. Full predictions and raw requests/responses are saved alongside the presentation.'))
s=s.replace('</main>',''.join(new)+'</main>')
s=s.replace('01 / 11','01 / 15')
css='''.endpoint{font:clamp(16px,1.8vw,25px) monospace;margin:0 0 40px;color:#52704c}.contract{display:grid;grid-template-columns:1fr 60px 1fr;gap:3vw;align-items:center}.contract>div{border-top:2px solid #52704c;padding-top:16px}.contract h3{font-size:32px;margin:10px 0 28px}.contract p{font-size:clamp(18px,1.8vw,25px);margin:24px 0}.contract code{display:block;color:#52704c;font-size:1.1em;margin-bottom:8px}.arrow{font-size:55px}pre{font-size:clamp(14px,1.65vw,24px);line-height:1.45;white-space:pre-wrap;margin:0;color:#33502e}.features{font-size:clamp(18px,1.7vw,25px);margin:0}.features>div{display:flex;justify-content:space-between;border-bottom:1px solid #d2d7c8;padding:8px 0}.features dd{font-weight:bold;margin:0}.resultbars>div{display:grid;grid-template-columns:34% 1fr 70px;gap:20px;align-items:center;margin:22px 0;font-size:clamp(18px,1.9vw,27px)}.resultbars>div>div{height:42px;background:#e0e5d5}.resultbars i{display:block;height:100%;background:#9ca78a}.resultbars>div:first-child i{background:#52704c}.matrix th{font-size:17px;text-transform:none;letter-spacing:0}.matrix td{font-size:48px;text-align:center}.matrix .right{background:#dce7cb}.matrix .wrong{background:#ecd8c9}@media(max-width:700px){.contract{grid-template-columns:1fr;gap:15px}.contract .arrow{display:none}.contract h3{font-size:24px;margin:5px 0 12px}.contract p{margin:12px 0}.resultbars>div{grid-template-columns:42% 1fr 45px;gap:8px}.resultbars>div>div{height:30px}.matrix th{font-size:13px}.matrix td{font-size:30px}.endpoint{overflow-wrap:anywhere}}'''
s=s.replace('</style>',css+'</style>')
s=re.sub(r'aria-label="Slide [123] of 3"','',s)
p.write_text(s)
(root/'check-script.js').write_text(re.search(r'<script>(.*?)</script>',s,re.S).group(1))
assert s.count('<section')==15
print('15 slides; API contract and actual results added.')
# Independently recalculate reported result from persisted records.
records=[json.loads((out/f'passenger-{i}.json').read_text()) for i in m['passenger_ids']]
assert len(records)==100
assert sum(r['actual']==r['predicted'] for r in records)==72
assert all('Survived' not in json.dumps(r['request']) and 'PassengerId' not in json.dumps(r['request']) and 'Name' not in json.dumps(r['request']) for r in records)
print('Reconciled all 100 saved predictions; no label or identifier in requests.')
